        memberCount = 1
    end
    if losses == nil then
        losses = 0
    end
    local targetEfficiency = ____exports.efficiency(baseName)
    local minimum = cs.MINIMUM_EFFICIENCY
    local defence = (targetEfficiency - minimum) / (1 - minimum)
