        local available = supply.reserve_side(side, role)
        do
            local index = 0
            while index < math.min(available, requested) do
                if not supply.consume_side(side, role, 1) then
                    break
                end
                index = index + 1
            end
        end
    end
    shrink(oldSide, "heli", CAPTURE_REGEN_HELI)
    shrink(oldSide, "striker", CAPTURE_REGEN_FW)
